<template>
	<view class="detail-page">
		<view class="fixed-header" :style="{ paddingTop: statusBarHeight + 'px' }">
			<view class="nav-bar">
				<view class="back-btn" @click="goBack">‹</view>
				<text class="nav-title">瓶子详情</text>
				<view v-if="note && !note.mine" class="report-btn" @click="submitReport">举报</view>
				<view v-else class="report-placeholder"></view>
			</view>
		</view>

		<scroll-view class="detail-scroll" scroll-y enhanced :show-scrollbar="false" :style="{ paddingTop: headerHeight + 'px' }">
			<view v-if="loading" class="state-card">正在打开这封信...</view>
			<view v-else-if="loadError" class="state-card error-state">
				<text>{{ loadError }}</text>
				<view class="retry-btn" @click="loadDetail">重新加载</view>
			</view>
			<template v-else-if="note">
			<view class="letter-card">
				<view class="stamp">DRIFT</view>
				<text class="letter-title">{{ authorName }}</text>
				<text class="letter-meta">{{ formatTime(note.createdAt) }} · {{ replyStateText }}</text>
				<text class="letter-content">{{ note.content }}</text>
				<view class="tag-row">
					<text v-for="tag in note.tags || []" :key="tag" class="tag-chip"># {{ tag }}</text>
				</view>
			</view>

			<view v-if="canReply" class="reply-card">
				<text class="section-title">回一封信</text>
				<textarea
					v-model="replyText"
					class="reply-input"
					placeholder="先回信，再决定是否连接。"
					placeholder-class="placeholder"
					maxlength="300"
					auto-height
				/>
				<view class="reply-actions">
					<view class="soft-btn" @click="skipNote">暂时跳过</view>
					<view class="main-btn" :class="{ disabled: submitting }" @click="sendReply">{{ submitting ? '发送中...' : '发送回信' }}</view>
				</view>
			</view>

			<view v-else class="reply-card disabled-card">
				<text class="section-title">暂时不能回信</text>
				<text class="disabled-copy">{{ replyStateText }}</text>
			</view>

			<view v-if="note.thread && note.thread.length" class="timeline-card">
				<text class="section-title">已经收到的回信</text>
				<view v-for="item in note.thread" :key="item.id" class="reply-item">
					<text class="reply-author">{{ getReplyAuthor(item) }} · {{ formatTime(item.createdAt) }}</text>
					<text class="reply-content">{{ item.content }}</text>
				</view>
			</view>
			</template>

			<view class="bottom-safe"></view>
		</scroll-view>
	</view>
</template>

<script>
import { fetchNoteDetail, replyNote, reportNote } from '../../api/note';
import { showRequestError } from '../../utils/feedback';
import * as profileGuard from '../../utils/profileGuard';

export default {
	data() {
		return {
			statusBarHeight: 44,
			headerHeight: 96,
			noteId: '',
			note: null,
			loading: false,
			loadError: '',
			submitting: false,
			replyText: '',
			reporting: false
		};
	},
	computed: {
		authorName() {
			const author = (this.note && this.note.author) || {};
			return author.nickname || author.stampNo || '一位同频旅人';
		},
		canReply() {
			return Boolean(this.note && this.note.allowReply !== false && !this.note.expired);
		},
		replyStateText() {
			if (!this.note) return '';
			if (this.note.expired) return '这封信已经过期';
			return this.note.allowReply === false ? '主人没有开启回信' : '可以回信';
		}
	},
	onLoad(query = {}) {
		this.setHeaderHeight();
		this.noteId = query.id || query.noteId || '';
		this.loadDetail();
	},
	methods: {
		setHeaderHeight() {
			try {
				const info = uni.getSystemInfoSync();
				this.statusBarHeight = info.statusBarHeight || 44;
				const rpxToPx = (info.windowWidth || 375) / 750;
				this.headerHeight = this.statusBarHeight + Math.round(96 * rpxToPx);
			} catch (error) {
				this.headerHeight = 96;
			}
		},
		async loadDetail() {
			if (!this.noteId) {
				this.loadError = '缺少纸条信息';
				return;
			}
			this.loading = true;
			this.loadError = '';
			try {
				this.note = await fetchNoteDetail(this.noteId);
			} catch (error) {
				this.loadError = (error && error.message) || '纸条加载失败';
			} finally {
				this.loading = false;
			}
		},
		async sendReply() {
			if (!this.canReply || this.submitting) return;
			if (!this.replyText.trim()) {
				uni.showToast({ title: '先写一点回信内容', icon: 'none' });
				return;
			}
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '回信' }))) return;
			this.submitting = true;
			try {
				await replyNote(this.noteId, { content: this.replyText.trim() });
				this.replyText = '';
				uni.showToast({ title: '回信已发送', icon: 'success' });
				await this.loadDetail();
			} catch (error) {
				showRequestError(error, '回信失败');
			} finally {
				this.submitting = false;
			}
		},
		async submitReport() {
			if (!this.note || this.reporting) return;
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '举报' }))) return;
			uni.showActionSheet({
				itemList: ['垃圾广告', '骚扰或攻击', '违法违规', '泄露隐私', '其他不适内容'],
				success: async ({ tapIndex }) => {
					const reasons = ['垃圾广告', '骚扰或攻击', '违法违规', '泄露隐私', '其他不适内容'];
					this.reporting = true;
					try {
						await reportNote(this.noteId, reasons[tapIndex]);
						uni.showToast({ title: '举报已提交', icon: 'success' });
					} catch (error) {
						showRequestError(error, '举报失败');
					} finally {
						this.reporting = false;
					}
				}
			});
		},
		formatTime(value) {
			const date = new Date(value || '');
			if (!date.getTime()) return '刚刚';
			return `${date.getMonth() + 1}月${date.getDate()}日 ${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
		},
		getReplyAuthor(item = {}) {
			const author = item.author || {};
			return author.nickname || author.stampNo || '同频旅人';
		},
		skipNote() {
			this.goBack();
		},
		goBack() {
			uni.navigateBack();
		}
	}
};
</script>

<style lang="scss" scoped>
.detail-page {
	min-height: 100vh;
	background: #f7f3f6;
}

.fixed-header {
	position: fixed;
	top: 0;
	left: 0;
	right: 0;
	z-index: 10;
	background: rgba(255, 255, 255, 0.97);
	border-bottom: 1rpx solid #f0e5ea;
}

.nav-bar {
	position: relative;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 96rpx;
	padding: 0 28rpx;
}

.back-btn,
.report-btn,
.report-placeholder {
	display: flex;
	align-items: center;
	justify-content: center;
	min-width: 72rpx;
	height: 72rpx;
	color: #d4688a;
	font-size: 26rpx;
	font-weight: 700;
}

.state-card {
	margin: 24rpx;
	padding: 80rpx 32rpx;
	border-radius: 24rpx;
	background: #ffffff;
	color: #9c8c95;
	font-size: 26rpx;
	text-align: center;
}

.error-state {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 24rpx;
}

.retry-btn {
	padding: 14rpx 28rpx;
	border-radius: 999rpx;
	background: #f9eef3;
	color: #b45e7b;
}

.main-btn.disabled {
	opacity: 0.55;
}

.disabled-card {
	text-align: center;
}

.disabled-copy {
	color: #9c8c95;
	font-size: 25rpx;
}

.reply-item {
	padding: 22rpx 0;
	border-top: 1rpx solid #f1ecef;
}

.reply-author,
.reply-content {
	display: block;
}

.reply-author {
	color: #a6959f;
	font-size: 21rpx;
}

.reply-content {
	margin-top: 10rpx;
	color: #33262e;
	font-size: 27rpx;
	line-height: 1.7;
}

.back-btn {
	font-size: 52rpx;
	color: #33262e;
}

.nav-title {
	position: absolute;
	left: 150rpx;
	right: 150rpx;
	text-align: center;
	font-size: 32rpx;
	font-weight: 700;
	color: #221820;
}

.detail-scroll {
	height: 100vh;
}

.letter-card,
.reply-card,
.timeline-card {
	margin: 24rpx;
	padding: 30rpx;
	border-radius: 26rpx;
	background: #ffffff;
	box-shadow: 0 10rpx 28rpx rgba(90, 55, 76, 0.06);
}

.letter-card {
	position: relative;
	overflow: hidden;
	background:
		linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(255, 252, 253, 0.99)),
		repeating-linear-gradient(180deg, transparent 0, transparent 64rpx, rgba(212, 104, 138, 0.08) 65rpx);
}

.stamp {
	position: absolute;
	top: 26rpx;
	right: 24rpx;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 112rpx;
	height: 112rpx;
	border-radius: 50%;
	border: 2rpx solid rgba(212, 104, 138, 0.36);
	color: rgba(212, 104, 138, 0.72);
	font-size: 20rpx;
	font-weight: 800;
	transform: rotate(10deg);
}

.letter-title {
	display: block;
	padding-right: 120rpx;
	font-size: 36rpx;
	line-height: 1.35;
	font-weight: 800;
	color: #241b22;
}

.letter-meta {
	display: block;
	margin-top: 14rpx;
	font-size: 23rpx;
	color: #a6959f;
}

.letter-content {
	display: block;
	margin-top: 34rpx;
	font-size: 30rpx;
	line-height: 1.9;
	color: #33262e;
}

.tag-row {
	display: flex;
	flex-wrap: wrap;
	gap: 12rpx;
	margin-top: 28rpx;
}

.tag-chip {
	display: inline-flex;
	align-items: center;
	height: 46rpx;
	padding: 0 16rpx;
	border-radius: 999rpx;
	background: #f9eef3;
	color: #b45e7b;
	font-size: 22rpx;
}

.section-title {
	display: block;
	margin-bottom: 20rpx;
	font-size: 30rpx;
	font-weight: 800;
	color: #241b22;
}

.reply-input {
	width: 100%;
	min-height: 220rpx;
	padding: 22rpx;
	border-radius: 20rpx;
	background: #faf7f9;
	font-size: 28rpx;
	line-height: 1.75;
	color: #33262e;
}

.placeholder {
	color: #c8b9c1;
}

.reply-actions {
	display: flex;
	gap: 14rpx;
	margin-top: 22rpx;
}

.soft-btn,
.main-btn {
	flex: 1;
	display: flex;
	align-items: center;
	justify-content: center;
	height: 72rpx;
	border-radius: 999rpx;
	font-size: 24rpx;
}

.soft-btn {
	background: #f6f1f4;
	color: #6f616a;
}

.main-btn {
	background: #221820;
	color: #ffffff;
	font-weight: 700;
}

.timeline-item {
	display: flex;
	gap: 18rpx;
	padding: 16rpx 0;
}

.timeline-dot {
	width: 22rpx;
	height: 22rpx;
	margin-top: 8rpx;
	border-radius: 50%;
	background: #e7dfe4;
	flex-shrink: 0;
}

.timeline-dot.active {
	background: #d4688a;
}

.timeline-copy {
	flex: 1;
	min-width: 0;
}

.timeline-title {
	display: block;
	font-size: 27rpx;
	font-weight: 700;
	color: #33262e;
}

.timeline-desc {
	display: block;
	margin-top: 8rpx;
	font-size: 23rpx;
	line-height: 1.55;
	color: #9c8c95;
}

.bottom-safe {
	height: calc(70rpx + env(safe-area-inset-bottom));
}
</style>
